var content = K.Stack(9,
    new Grid
    {
        ColumnDefinitions = new ColumnDefinitions("*,Auto"),
        Children =
        {
            K.Stack(2,
                K.Text("Add rate limiting to the public API", "arc-heading", 520),
                K.Row(6, K.Mark("anthropic", 15), K.Caption("Claude Sonnet 5.5"),
                    K.Dot(ArcTokens.BorderStrong, 3), K.Caption("arc-ui/api"),
                    K.Dot(ArcTokens.BorderStrong, 3), K.Caption("01:12"))),
            K.Row(6, state, K.IconBtn("refresh-cw", "Restart run"))
        }
    },
    K.Divider(2),
    K.Caption("Steps"),
    steps,          // 已完成的步骤与 waiting 步骤
    folded,         // 批准后收起为一句 Ran 5 steps
    approvalHost,   // 批准门：diff、说明输入与两个决定
    resultHost,     // 批准后展开的结果
    status);

return K.Surface(new Border { Child = content, MaxWidth = 880 }, new Thickness(22, 15, 22, 15));

var fileTabs = K.Row(6,
    K.Chip("src/api/rate-limit.ts", selected: !testFile),
    K.Chip("src/api/rate-limit.test.ts", selected: testFile));

var diffHost = new StackPanel { Spacing = 1 };
diffHost.Children.Add(K.DiffLine("ctx", "export function take(key: string) {"));
diffHost.Children.Add(K.DiffLine("del", "  return true;"));
diffHost.Children.Add(K.DiffLine("add", "  const bucket = buckets.get(key) ?? newBucket();"));
diffHost.Children.Add(K.DiffLine("add", "  if (bucket.spent >= bucket.limit) return false;"));
diffHost.Children.Add(K.DiffLine("ctx", "}"));

var actions = K.Row(6,
    K.Btn("Reject", ArcButtonVariant.Ghost, ArcButtonSize.Sm, ShowNote, icon: "x"),
    K.Btn("Approve", ArcButtonVariant.Primary, ArcButtonSize.Sm, Approve, icon: "check"));

var card = K.TintedInset(K.Stack(7,
    K.Row(7, K.Label("Review changes to 2 files"), K.Caption("+38 −6")),
    fileTabs,
    K.Inset(diffHost),
    K.Caption("Nothing is written until you approve."),
    actions), ArcTokens.Warning, 0.06);
